class Solution:
    def rotate(self, nums: list[int], k: int) -> None:
        n = len(nums)
        k %= n                               # rotating by n is the identity

        def reverse(l: int, r: int) -> None:
            while l < r:
                nums[l], nums[r] = nums[r], nums[l]
                l += 1
                r -= 1

        reverse(0, n - 1)        # whole array: the last k elements are now in front, reversed
        reverse(0, k - 1)        # first k elements
        reverse(k, n - 1)        # the rest; every element is swapped at most twice
